WITH target_powers AS (
  SELECT id FROM superpower WHERE power_name IN ('super speed', 'death touch')
), heroes_with_powers AS (
  SELECT DISTINCT hero_id FROM hero_power WHERE power_id IN (SELECT id FROM target_powers)
), intelligence_attribute AS (
  SELECT id FROM attribute WHERE attribute_name = 'intelligence'
)
SELECT ROUND(AVG(ha.attribute_value), 1) AS avg_intelligence
FROM heroes_with_powers hwp
JOIN hero_attribute ha ON hwp.hero_id = ha.hero_id
WHERE ha.attribute_id = (SELECT id FROM intelligence_attribute)
  AND ha.attribute_value IS NOT NULL;

WITH RA_Patients AS (
  SELECT Patient.ID, Patient.SEX
  FROM Patient
  INNER JOIN Examination ON Patient.ID = Examination.ID
  WHERE Examination.Diagnosis LIKE '%RA%'
),
Normal_UN AS (
  SELECT DISTINCT ID
  FROM Laboratory
  WHERE UN BETWEEN 7 AND 20
)

SELECT (
  SELECT COUNT(*) FROM RA_Patients WHERE SEX = 'F' AND ID IN (SELECT ID FROM Normal_UN)
) - (
  SELECT COUNT(*) FROM RA_Patients WHERE SEX = 'M' AND ID IN (SELECT ID FROM Normal_UN)
) AS Female_Minus_Male_Difference;

SELECT COUNT(DISTINCT ID) AS psoriatic_arthritis_patient_count
FROM Patient
WHERE Diagnosis = 'psoriatic arthritis';

