WITH bonds_expanded AS (
    SELECT molecule_id, atom_id1, atom_id2, bond_type
    FROM (
        SELECT b.molecule_id, c.atom1 AS atom_id1, c.atom2 AS atom_id2, b.bond_type 
        FROM bond b, connected c
        WHERE b.bond_id = c.bond_id
    )
), single_atoms AS (
    SELECT atom_id1 AS atom_id FROM bonds_expanded WHERE bond_type='single'
    UNION
    SELECT atom_id2 AS atom_id FROM bonds_expanded WHERE bond_type='single'
), iodine_atoms AS (
    SELECT DISTINCT atom_id FROM single_atoms s JOIN atom a ON s.atom_id=a.atom_id WHERE a.element='I'
), sulfur_atoms AS (
    SELECT DISTINCT atom_id FROM single_atoms s JOIN atom a ON s.atom_id=a.atom_id WHERE a.element='S'
)
SELECT 
    (SELECT COUNT(*) FROM iodine_atoms) AS distinct_iodine_atoms,
    (SELECT COUNT(*) FROM sulfur_atoms) AS distinct_sulfur_atoms;
